// One email per subscriber, sharing the same "what's new" list but each
// carrying that subscriber's own signed unsubscribe link. Escaped here
// rather than trusted, the same rule the admin digest follows — model
// blurbs are LLM-drafted from provider pages and could contain characters
// that would otherwise break the HTML.
const d = $input.first().json;

const esc = (s) =>
  String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

const STATUS_LABEL = { rumored: 'Rumored', announced: 'Announced', released: 'Released' };

const rows = d.newModels
  .map((m) => `
    <tr><td style="padding:12px 0;border-bottom:1px solid #e6e4df;">
      <div style="font:600 15px/1.4 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#15140f;">
        ${esc(m.name)} <span style="font-weight:400;color:#6f6b60;">· ${esc(m.provider)}</span>
        <span style="font:700 10px/1 ui-monospace,SFMono-Regular,Menlo,monospace;color:#8a8578;text-transform:uppercase;letter-spacing:.06em;margin-left:6px;">${esc(STATUS_LABEL[m.status] || m.status)}</span>
      </div>
      ${m.providerBlurb ? `<div style="font:400 14px/1.5 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#33312a;margin-top:4px;">${esc(m.providerBlurb).slice(0, 220)}</div>` : ''}
    </td></tr>`)
  .join('');

const n = d.newModels.length;
const subject = `trackai — ${n} new model${n === 1 ? '' : 's'} on the timeline`;

const htmlFor = (unsubscribeUrl) => `<!doctype html><html><body style="margin:0;padding:0;background:#faf9f6;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#faf9f6;padding:28px 12px;">
    <tr><td align="center">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:14px;padding:26px;">
        <tr><td>
          <div style="font:800 21px/1.2 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#15140f;">${n} new on the timeline</div>
          <div style="font:400 14px/1.5 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#6f6b60;margin-top:5px;">Rumored, announced, or released — whatever showed up since your last update.</div>
        </td></tr>
        <tr><td><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:6px;">${rows}</table></td></tr>
        <tr><td style="padding-top:22px;">
          <a href="https://trackai.theaugustdispatch.com" style="display:inline-block;background:#e8b73a;color:#1a1710;text-decoration:none;font:700 15px/1 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;padding:14px 26px;border-radius:999px;">See the timeline</a>
        </td></tr>
        <tr><td style="padding-top:20px;">
          <a href="${esc(unsubscribeUrl)}" style="font:400 12px/1.5 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#8a8578;">Unsubscribe from release alerts</a>
        </td></tr>
      </table>
    </td></tr>
  </table>
</body></html>`;

return d.subscribers.map((s) => ({
  json: { email: s.email, subject, html: htmlFor(s.unsubscribeUrl) },
}));

// Only reached once every Gmail send above has completed — mark the
// models as alerted now, not before, so a failed send would leave them
// eligible for tomorrow's run instead of silently vanishing.
const ids = $('GET digest').first().json.newModels.map((m) => m.id);
return [{ json: { modelIds: ids } }];
